import{_ as s,c as i,o as a,ah as t,j as e,a as r}from"./chunks/framework.CAZQ2vdu.js";const d="/Qonnectra-docs/pr-17/images/manual/teil-a/compaction.jpg",u="/Qonnectra-docs/pr-17/images/manual/teil-a/compaction_search.jpg",h="/Qonnectra-docs/pr-17/videos/compaction_search.webm",c="/Qonnectra-docs/pr-17/images/manual/teil-a/compaction_address.jpg",o="/Qonnectra-docs/pr-17/images/manual/teil-a/compaction_export.jpg",w=JSON.parse('{"title":"7. Nachverdichtung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/07-nachverdichtung.md","filePath":"manual/teil-a-anwenderhandbuch/07-nachverdichtung.md"}'),l={name:"manual/teil-a-anwenderhandbuch/07-nachverdichtung.md"};function m(g,n,b,p,f,k){return a(),i("div",null,[...n[0]||(n[0]=[t('<h1 id="_7-nachverdichtung" tabindex="-1">7. Nachverdichtung <a class="header-anchor" href="#_7-nachverdichtung" aria-label="Permalink to &quot;7. Nachverdichtung&quot;">​</a></h1><p>Die <strong>Nachverdichtung</strong> stellt zu einer einzelnen Adresse alle Angaben zusammen, die für einen nachträglichen Hausanschluss gebraucht werden, und gibt sie als PDF-Dokument aus – für die Montage vor Ort, für die Akte oder für die Weitergabe an ein ausführendes Unternehmen. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Funktionen“ durch Klicken auf den Menüpunkt „Nachverdichtung“.</p><p><img src="'+d+'" alt="Screenshot Nachverdichtung mit dem Suchfeld für Adressen" data-zoomable="true"></p><p>Die Ansicht führt durch drei Schritte: Adresse suchen, Angaben prüfen, PDF erzeugen. Bearbeiten lässt sich hier nichts – mit einer Ausnahme, dem Ausbaustatus, siehe Abschnitt <a href="#_7-3-ausbaustatus-andern-und-bemerkung-erfassen">Ausbaustatus ändern und Bemerkung erfassen</a>.</p><h2 id="_7-1-adresse-suchen" tabindex="-1">7.1 Adresse suchen <a class="header-anchor" href="#_7-1-adresse-suchen" aria-label="Permalink to &quot;7.1 Adresse suchen&quot;">​</a></h2><p>Geben Sie im Feld „Adresse suchen...“ einen Suchbegriff ein. Ab zwei Zeichen sucht Qonnectra von selbst, kurz nachdem Sie zu tippen aufgehört haben; einen Button zum Auslösen gibt es nicht. Darunter erscheinen die Treffer mit Straße, Hausnummer, Postleitzahl und Ort, darunter jeweils die Adress-ID.</p><p><img src="'+u+'" alt="Screenshot Nachverdichtung mit Hervorhebung des Suchfelds und der Trefferliste darunter" data-zoomable="true"></p>',7),e("p",null,[e("video",{src:h,controls:"",playsinline:"",preload:"metadata"},[r(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/compaction_search.webm",download:""},"herunterladen"),r(" anstelle des Videos. ")])],-1),t('<p>Gesucht wird nur innerhalb des Projekts, das oben links in der Kopfzeile ausgewählt ist, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>. Durchsucht werden „Straße“, „Ort“, „PLZ“ und „Ortsteil“ sowie „Hausnummer“ und „Adress-ID“. Mehrere durch Leerzeichen getrennte Wörter müssen alle zutreffen: „Toft 1“ findet die Adressen der Straße Toft, deren Hausnummer eine 1 enthält – also auch die Nummern 10, 17 und 21.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Suche über „Straße“, „Ort“, „PLZ“ und „Ortsteil“ ist unscharf: Sie verzeiht Tippfehler und sortiert die Treffer nach Ähnlichkeit, nicht alphabetisch. Bei mehreren Wörtern richtet sich die Reihenfolge allein nach dem ersten. Angezeigt werden höchstens 20 Adressen. Grenzen Sie den Suchbegriff ein, wenn die gesuchte Adresse nicht dabei ist; „Keine Ergebnisse gefunden“ erscheint erst, wenn gar nichts passt.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Unschärfe holt auch ähnlich geschriebene Straßen herein: „Toft“ findet ebenso die Adressen der Straße „Oster Torf“. Prüfen Sie deshalb bei jedem Treffer den Straßennamen, bevor Sie ihn anklicken – die Trefferliste zeigt keinen Hinweis darauf, wie gut ein Eintrag gepasst hat.</p><p>Wörter mit weniger als drei Zeichen sucht Qonnectra dagegen buchstäblich, dafür zusätzlich in „Hausnummer“, „Hausnummernzusatz“ und „Adress-ID“. Eine „1“ kann deshalb auch über eine Adress-ID oder eine Postleitzahl treffen und nicht über die Hausnummer.</p></div><h2 id="_7-2-angaben-zur-adresse-und-kartenausschnitt" tabindex="-1">7.2 Angaben zur Adresse und Kartenausschnitt <a class="header-anchor" href="#_7-2-angaben-zur-adresse-und-kartenausschnitt" aria-label="Permalink to &quot;7.2 Angaben zur Adresse und Kartenausschnitt&quot;">​</a></h2><p>Mit dem Klick auf einen Treffer tritt an die Stelle des Suchfelds die gewählte Adresse. Darunter stehen „Adress-ID“, „Straße“, „Hausnummer“, „PLZ“, „Ort“ und „Ortsteil“, darunter ein Kartenausschnitt mit der Adresse und dem Weg der Kabel, die sie versorgen.</p><p><img src="'+c+'" alt="Screenshot Nachverdichtung mit Hervorhebung der Adressangaben und des Kartenausschnitts" data-zoomable="true"></p><p>Der Ausschnitt ist beim Öffnen auf die Adresse zentriert, lässt sich aber wie jede andere Karte verschieben und zoomen. Legende, Suche und Transparenzregler fehlen ihm, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>; Strecke und Fläche messen können Sie dagegen auch hier, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-5-strecke-und-flache-messen">Strecke und Fläche messen</a>. Sind für das Projekt WMS-Dienste eingerichtet, werden deren Layer mitgezeichnet, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Linie im Ausschnitt ist der ermittelte <strong>Kabelweg</strong> zur Adresse und nicht die Trasse, auch wenn sie in der Trassenfarbe gezeichnet ist: Qonnectra verfolgt die Fasern der Adresse über ihre Spleiße zurück und zeichnet die Strecke, die die gefundenen Kabel nehmen, siehe Kapitel <a href="./15-faserweg.html">Faserweg</a>. Sie verläuft damit in den Trassen, deckt aber nur den Teil des Netzes ab, der die Adresse wirklich versorgt. Erst wenn sich kein Faserweg ermitteln lässt, zeichnet Qonnectra stattdessen die Trassen, deren Rohre über ein Mikrorohr an der Adresse hängen.</p></div><p>Über das Kreuz rechts neben der Adresse kommen Sie zur Suche zurück. Ein Projektwechsel setzt die Auswahl ebenfalls zurück.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Hat die Adresse keine Koordinaten, steht an dieser Stelle „Keine Standortdaten verfügbar“. Das PDF enthält dann weder Karte noch Koordinaten; alles Übrige wird erzeugt.</p></div><h2 id="_7-3-ausbaustatus-andern-und-bemerkung-erfassen" tabindex="-1">7.3 Ausbaustatus ändern und Bemerkung erfassen <a class="header-anchor" href="#_7-3-ausbaustatus-andern-und-bemerkung-erfassen" aria-label="Permalink to &quot;7.3 Ausbaustatus ändern und Bemerkung erfassen&quot;">​</a></h2><p>Der Button „Start“ öffnet das Fenster „Nachverdichtung“. Es wiederholt „Adress-ID“, „Straße“, „PLZ“ und „Ort“ und enthält darunter zwei Felder.</p><p><strong>„Ausbaustatus“</strong> ist mit dem Status vorbelegt, den die Adresse derzeit hat. Zur Auswahl stehen die Werte, die in den Stammdaten hinterlegt sind, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-7-stammdaten-status-phase-netzebene-firmen">Stammdaten</a>.</p><p><strong>„Kommentar“</strong> nimmt einen freien Text auf, etwa eine Absprache mit den Eigentümer*Innen oder einen Hinweis für die Montage.</p><p><img src="'+o+'" alt="Screenshot Nachverdichtung mit dem geöffneten Fenster „Nachverdichtung“ und den Feldern „Ausbaustatus“ und „Kommentar“" data-zoomable="true"></p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Ein geänderter Ausbaustatus landet nicht nur im Dokument: Mit „Exportieren“ wird er an der Adresse gespeichert, gemeldet durch „Adresse erfolgreich aktualisiert“. Wenn Sie den Status nur für das Dokument ändern wollten, ist das nicht möglich – die Adresse ist danach geändert. „Abbrechen“ verwirft die Änderung.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Der Kommentar wird umgekehrt <strong>nicht</strong> gespeichert. Er steht nur in dem einen Dokument; beim nächsten Öffnen des Fensters ist das Feld wieder leer. Was dauerhaft an der Adresse hängen soll, gehört in deren Angaben oder als Datei in die Anhänge, siehe Kapitel <a href="./16-adressen.html">Adressen</a>.</p></div><h2 id="_7-4-pdf-erzeugen-und-inhalt-des-dokuments" tabindex="-1">7.4 PDF erzeugen und Inhalt des Dokuments <a class="header-anchor" href="#_7-4-pdf-erzeugen-und-inhalt-des-dokuments" aria-label="Permalink to &quot;7.4 PDF erzeugen und Inhalt des Dokuments&quot;">​</a></h2><p>„Exportieren“ erzeugt das Dokument und lädt es unter dem Namen <code>Straße_Hausnummer.pdf</code> herunter. Das Fenster schließt sich, und Qonnectra meldet „PDF erfolgreich heruntergeladen“.</p><p>Die erste Seite trägt die Adresse als Überschrift und enthält:</p><ul><li><strong>„Adressinformationen“</strong> – „Adress-ID“, „Straße“, „Hausnummer“, „PLZ“, „Ort“ und „Ortsteil“.</li><li><strong>„Klassifizierung“</strong> – „Ausbaustatus“, „Kennzeichen“ und „Projekt“.</li><li>den <strong>Kartenausschnitt</strong> aus Abschnitt <a href="#_7-2-angaben-zur-adresse-und-kartenausschnitt">Angaben zur Adresse und Kartenausschnitt</a>, und zwar so, wie er beim Export auf dem Bildschirm steht – haben Sie ihn vorher verschoben oder gezoomt, steht dieser Ausschnitt im Dokument. Darunter folgen die Koordinaten der Adresse zweimal: in dem Koordinatensystem, in dem Qonnectra die Geometrien führt, und in EPSG:4326, also in geografischer Breite und Länge. Vor jedem Wert steht die EPSG-Kennung des jeweiligen Systems.</li><li><strong>„Mikrorohrverbindungen“</strong> – die Mikrorohre der Netzknoten, die an der Adresse hängen, mit den Spalten „Überg. Netzknoten“, „Netzknoten“, „Rohrname“, „Rohrtyp“, „Nummer“ und „Farbe“.</li><li><strong>„Kommentar“</strong>, sofern Sie einen erfasst haben.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Für das Dokument wird der Kartenausschnitt so abfotografiert, wie er auf dem Bildschirm liegt – mit allem, was gerade darin gezeichnet ist. Eine Messung aus Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-5-strecke-und-flache-messen">Strecke und Fläche messen</a>, die Sie nicht über „Messung beenden“ aufgeräumt haben, steht deshalb mit im PDF. Räumen Sie sie vor dem Export weg.</p></div><p>Danach folgt eine Seite je Wohneinheit der Adresse, in dieser Reihenfolge: „Wohneinheit-ID“ (ID und die beiden externen Kennungen), „Klassifizierung“ („Typ“ und „Status“), „Standort“ („Etage“, „Seite“, „Gebäudeteil“) und „Bewohner“ („Name des Bewohners“, „Erfassungsdatum Bewohner“, „Betriebsbereit“). Sind der Wohneinheit Fasern zugeordnet, steht darunter „Faserverbindungen“ mit den Spalten „Überg. Netzknoten“, „Netzknoten“, „Kabelname“, „Absolute Faser“, „Bündel“ und „Faser“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Das Dokument wird im Browser erzeugt und nur heruntergeladen. Qonnectra legt keine Kopie ab – wer es später wiederfinden soll, braucht es als Anhang an der Adresse, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Schlägt die Erzeugung fehl, meldet Qonnectra „Fehler beim Erstellen der PDF“ und es wird nichts heruntergeladen. Ein bereits geänderter Ausbaustatus ist dann trotzdem gespeichert.</p></div>',25)])])}const S=s(l,[["render",m]]);export{w as __pageData,S as default};
